type User = { id: string; name: string };

function isUser(value: unknown): value is User {
  return typeof value === 'object'
    && value !== null
    && 'id' in value
    && typeof value.id === 'string'
    && 'name' in value
    && typeof value.name === 'string';
}

function parseUser(json: string): User {
  const value: unknown = JSON.parse(json);
  if (!isUser(value)) throw new Error('Invalid user payload');
  return value;
}

const user = parseUser('{"id":"u1","name":"Ada"}');
console.log(user.name);

interface Entity {
  id: string;
}

interface User extends Entity {
  name: string;
}

type LoadState =
  | { status: 'loading' }
  | { status: 'success'; user: User }
  | { status: 'error'; message: string };

function describe(state: LoadState): string {
  if (state.status === 'success') return state.user.name;
  if (state.status === 'error') return state.message;
  return 'Loading…';
}

console.log(describe({ status: 'loading' }));

async function getUser(id: string) {
