type Action =
  | { type: 'save'; id: string }
  | { type: 'delete'; id: string }
  | { type: 'reset' };

type ItemAction = Extract<Action, { id: string }>;
type ResetAction = Exclude<Action, { id: string }>;

function handleItemAction(action: ItemAction): string {
  return `${action.type}: ${action.id}`;
}

const message = handleItemAction({ type: 'save', id: 'a1' });
